window.RP_SESSION={"id":"S-90c832668297","messages":[{"id":"RP-0031994","time":"2026-02-06T10:48:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"ㅁ...\"\n\n미음? 라르손, 컨디션이 별로 안좋아 보이더니 미음으로 끼니를 떼우고 있는걸까요?\n\n\"ㅁ...\"\n\n아니면, 뭔가 미움...? 미운가요?","characters":["P-b551ad21c43a"]},{"id":"RP-0031995","time":"2026-02-06T10:48:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"맥주!\"","characters":["P-b551ad21c43a"]},{"id":"RP-0031996","time":"2026-02-06T10:48:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-b551ad21c43a"]},{"id":"RP-0031997","time":"2026-02-06T10:49:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"라르손은 대낮부터 길드 식당에 앉아서 소세지, 바짝 익힌 감자, 그리고 맥주를 마시고 있습니다. 드워프들은 다 이런가요?","characters":["P-b551ad21c43a"]},{"id":"RP-0031998","time":"2026-02-06T10:51:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"그래도 혼자 먹을 생각은 아닌지 누가 봐도 1인분은 아닌 커다란 맥주통을 들고 왔네요, 라르손. 1인분은 아닌... 게 맞겠죠?","characters":["P-b551ad21c43a"]},{"id":"RP-0031999","time":"2026-02-06T10:52:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"빼꼼-","characters":["P-48cca58d02b2"]},{"id":"RP-0032000","time":"2026-02-06T10:53:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"어라? 안녕하세요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032001","time":"2026-02-06T10:54:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"텃밭에라도 다녀왔는지 흙이 잔뜩 묻은 손으로 반갑게 손을 흔듭니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0032002","time":"2026-02-06T10:57:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"어서 오시게!\"\n\n라르손은 맥주잔을 왼손으로 들고 오른손을 반갑게 흔들며 인사합니다.\n\n\"같이 한 잔 하지 않겠는가!\"","characters":["P-b551ad21c43a"]},{"id":"RP-0032003","time":"2026-02-06T10:59:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"앗! 지금 손이 이래서요. 금방 씻고 올게요!\"\n\n우다다하고 계단을 오르는 소리가 들렸다가. 잠시후 다시 같은 발소리가 식당을 향해옵니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0032004","time":"2026-02-06T10:59:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"짠! 다녀왔어요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032005","time":"2026-02-06T11:00:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"어서오게!\"\n\n그새 더 늘어난 소시지와 감자. 그리고 맥주...? 라르손. 정말 저 커다란 통을 혼자 마실 생각이었나요?\n\n맥주통 옆에 맥주통이 하나 더 늘어났네요.","characters":["P-b551ad21c43a"]},{"id":"RP-0032006","time":"2026-02-06T11:01:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그런데 뭘 마시고 계신 거예요? 뭔가 잔뜩 있네요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032007","time":"2026-02-06T11:03:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"라르손 옆으로 다가가 맥주통 안을 빼꼼히 들여다봅니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0032008","time":"2026-02-06T11:03:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"맥주일세! 같이 한 잔 하지 않겠나!\"\n\n모나에게 맥주가 가득 든 맥주잔을 건내네요.","characters":["P-b551ad21c43a"]},{"id":"RP-0032009","time":"2026-02-06T11:04:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"소시지와 감자를 조금 곁들이면 정말 죽여준다네!\"","characters":["P-b551ad21c43a"]},{"id":"RP-0032010","time":"2026-02-06T11:04:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"오와아..! 네, 그러면 잘 먹을게요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032011","time":"2026-02-06T11:05:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그런데 파티라도 하나요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032012","time":"2026-02-06T11:06:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"드워프는 이게 일상일세! 파티를 하면 맥주 분수 위에 드워프 몇 명이 꽂혀있지!\"\n\n과장입니다.\n\n\"그만큼 끝내준다네!\"\n\n감자는 기름을 두르고 바짝 구워서 바삭하고, 소시지는 향신료가 적절히 들어가서 맛도 향도 좋고, 맥주야... 말이 필요 없죠!","characters":["P-b551ad21c43a"]},{"id":"RP-0032013","time":"2026-02-06T11:10:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그렇구나아. 유랑단 가족분들도 매일 이렇게 파티를 열곤 하셨어요. 물론 누가 맥주 분수에 꽃히지는 않았지만!\"\n\n우선 소시지를 한입 크게 베어뭅니다. 겉껍질이 이빨에 잠깐 저항을하다가, 이내 곧 뽀드득하고 터지며 향긋한 육즙이 입안 퍼져나가네요. 그리고 그 뒤에 바로 맥주를 한 모금...!","characters":["P-48cca58d02b2"]},{"id":"RP-0032014","time":"2026-02-06T11:10:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"푸흐하..! 이거 정말 맛있어요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032015","time":"2026-02-06T11:11:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"굉장히 슈-퍼한 소시지와 맥주네요!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032016","time":"2026-02-06T11:12:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"으하하, 좋은 맥주, 좋은 소시지, 좋은 감자가 있으니 여기가 천국 아닌가!\"\n\n라르손은 감자를 포크로 찍어서 한 입 베어물어요. 목이 막히기 전에 맥주를 한 모금. 딱이네요!","characters":["P-b551ad21c43a"]},{"id":"RP-0032017","time":"2026-02-06T11:16:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그리고 함께 먹을 사람도 있으니 더 좋죠!\"\n\n그리곤 맥주를 몇 모금 더 마시자 흥이 오르기 시작했는지, 식탁을 통통 두드리며 노래를 흥얼거리기 시작합니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0032018","time":"2026-02-06T11:18:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"건배~!\"\n\n라르손은 잔을 치켜올리고 또 건배를 하더니, 맥주를 마시고 당신과 함께 노래를 흥얼거려요~ 물론 라르손은 지독한 음치지만요...","characters":["P-b551ad21c43a"]},{"id":"RP-0032019","time":"2026-02-06T11:22:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"건배~\"\n\n서로 음정박자가 엇나간 불협화음이 이어지지만, 전혀 아랑곳하지 않고 해맑게 웃으며 노래를 이어나갑니다. 이 또한 술자리의 흥취. 즐거우면 그만인거죠.","characters":["P-48cca58d02b2"]},{"id":"RP-0032020","time":"2026-02-06T11:22:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"헤헤. 왠지 유랑단 시절이 생각나서 신이나요~\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032021","time":"2026-02-06T11:23:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"술자리의 흥취가 대낮부터 이렇게 식당을 가득 메우는건 라르손이 들어온 이후로는 그리 드문 일이 아니게 되었으리라.","characters":["P-b551ad21c43a"]},{"id":"RP-0032022","time":"2026-02-06T11:24:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"크하하, 맥주를 마시세! 여기서 한잔, 추억 속에서 한잔! 또 한잔!\"","characters":["P-b551ad21c43a"]},{"id":"RP-0032023","time":"2026-02-06T11:26:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"와아! 한잔!\"\n\n그렇게 라르손을 따라 한 잔을 꼴깍꼴깍 비워내고, 어디서 배운 건지 머리 위로 빈 잔을 흔들흔들 흔드네요. 덕분에 남아있던 몇 방울에 머리카락이 촉촉해집니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0032024","time":"2026-02-06T11:27:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"하하, 잘 마시는구먼!\"\n\n또 모나에게 맥주를 한 잔 가득 따라주는 라르손. 아직 한 통의 절반도 안 비었는데 도대체 몇 잔이나 마신거죠?","characters":["P-b551ad21c43a"]},{"id":"RP-0032025","time":"2026-02-06T11:29:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"헤헤~ 감사합니다아~\"\n\n모나는 새로이 가득찬 맥주를 건네 받아, 소시지와 감자, 맥주를 번갈아 가며 입안에서 저글링을 벌입니다.\n살짝 혀가 꼬일랑 말랑한 것 같지만. 뭐 괜찮겠죠?","characters":["P-48cca58d02b2"]},{"id":"RP-0032026","time":"2026-02-06T11:33:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"맥주! 맥주를 마시면 언제나 기분이 좋아지지!\"\n\n라르손은 별로 취한 것 같지 않아요. 아마 평범한 사람이 보면 꽤 취했다고 생각하겠지만... 라르손은 평소에도 이러는걸요!","characters":["P-b551ad21c43a"]},{"id":"RP-0032027","time":"2026-02-06T11:37:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"쌉싸름한 맛이 묘하게 중독적이네요. 이게 아마 홉이던가요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032028","time":"2026-02-06T11:37:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"꽃 피기도 전에 따버리는 건 조금 아쉽지만. 덕분에 이렇게 맥주 안에서 새롭게 향을 피워내는 거겠죠!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032029","time":"2026-02-06T11:38:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"꼴깍꼴깍- 라르손과 달리 얼굴이 점점 붉게 달아오릅니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0032030","time":"2026-02-06T11:39:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"그렇지. 피어남은 어디서든 찾아볼 수 있는 법이야!\"\n\n라르손은 또 맥주를 따라주고는 소시지와 감자를 먹습니다. 배도 안 부른가봐요...\n\n\"맥주맛 같은 곳에서는 특히 더 쉽지!\"","characters":["P-b551ad21c43a"]},{"id":"RP-0032031","time":"2026-02-06T11:41:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"후흐흐~ 생각 난 김에 나중에 꽃밭에다 홉도 길러 봐야겠어요~\"\n\n그렇게 다시 새 잔을 받아들이고는, 어느덧 소시지를 먹는 것도 잊은 채 그냥 맥주만 꼴깍꼴깍 들이킵니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0032032","time":"2026-02-06T11:42:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-48cca58d02b2"]},{"id":"RP-0032033","time":"2026-02-06T11:42:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'모나 델핀'의 체력 판정 :\n[9] + [0] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0032034","time":"2026-02-06T11:42:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"좋네. 홉 상태로 나한테 팔면 가격은 잘 쳐주지!\"\n\n또 맥주를 따라주고, 소시지를 먹고...","characters":["P-b551ad21c43a"]},{"id":"RP-0032035","time":"2026-02-06T11:43:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"네에~ 길드의 가족분들께 도움이 되며언~ 저도 조아요~\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032036","time":"2026-02-06T11:44:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"보리꽃도 작지만 매력이 있는데에~\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032037","time":"2026-02-06T11:44:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"꼴깍꼴깍-","characters":["P-48cca58d02b2"]},{"id":"RP-0032038","time":"2026-02-06T11:45:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그런데 라르손 씨는 양조장인이었어요오?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032039","time":"2026-02-06T11:46:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"아직 어용단에 들어 온지 얼마 되지 않는 그녀이기에, 길드원의 이름과 얼굴을 외우는 것만으로도 조금 벅차보입니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0032040","time":"2026-02-06T11:48:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"연금술사일세. 맥주도 만들고, 물약도 만들고,증류주로도이것저것 만들고!\"\n\n또 맥주를 따라주고, 이번 안주는 감자로... 도대체 라르손, 얼마나 마시는거에요?","characters":["P-b551ad21c43a"]},{"id":"RP-0032041","time":"2026-02-06T11:51:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"오와아~ 릴리 할머니도 약사셨는데에~ 라르소온 씨이는 마치 할머니같네요오~\"\n\n그냥 봐도 제법 알딸딸해진 상태로 라르손이 따라준 맥주를 사양않고 받아 마십니다. 아직 발음을 알아 들을 수 있는 게 용하다 싶네요.","characters":["P-48cca58d02b2"]},{"id":"RP-0032042","time":"2026-02-06T11:51:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그러고 보니 이름도오~ 릴리~ 라르ㅅ..라리...릴리라리~ 흐헤헤~\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032043","time":"2026-02-06T11:52:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"그래도! 저희 할머니가 훨씬 더 복슬복슬해요~!\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032044","time":"2026-02-06T11:52:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"뿌듯-","characters":["P-48cca58d02b2"]},{"id":"RP-0032045","time":"2026-02-06T11:54:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"으하하...\"\n\n아무래도. 대머리라서 복슬복슬하진 않죠.","characters":["P-b551ad21c43a"]},{"id":"RP-0032046","time":"2026-02-06T11:54:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"자네 좀 취한 것 같네!\"\n\n이제 알았어요?","characters":["P-b551ad21c43a"]},{"id":"RP-0032047","time":"2026-02-06T11:55:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"\"저요오? 괜찮은 거 같은데요오?\"","characters":["P-48cca58d02b2"]},{"id":"RP-0032048","time":"2026-02-06T11:55:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-48cca58d02b2"]},{"id":"RP-0032049","time":"2026-02-06T11:55:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'모나 델핀'의 체력 판정 :\n[3] + [0] = [3]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0032050","time":"2026-02-06T11:55:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"쿵!","characters":["P-48cca58d02b2"]},{"id":"RP-0032051","time":"2026-02-06T11:55:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"그 말을 하자마자 소시지와 감자가 담긴 접시위로 모나의 얼굴이 엎어집니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0032052","time":"2026-02-06T11:56:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"이런 젠장! 취했으면 취했다고 말을 하지!\"","characters":["P-b551ad21c43a"]},{"id":"RP-0032053","time":"2026-02-06T11:57:00+09:00","room":"RP","name":"모나 델핀","profile":"페트라","identity":"reviewed","type":"dialogue","body":"아무래도 술을 많이 마셔본 적이 없었는지, 자기 주량을 몰랐던 모양입니다.","characters":["P-48cca58d02b2"]},{"id":"RP-0032054","time":"2026-02-06T11:58:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"라르손도 적당히 마시고 뒷정리를 하는 모양입니다~","characters":["P-b551ad21c43a"]},{"id":"RP-0032055","time":"2026-02-06T11:58:00+09:00","room":"RP","name":"라르손","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b551ad21c43a"]},{"id":"RP-0032056","time":"2026-02-06T11:58:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
